class Solution {
public:
    int makeStringGood(string s) {
        vector<int> cnt(26, 0);
        for (char ch : s) cnt[ch - 'a']++;
        int maxCnt = *max_element(cnt.begin(), cnt.end());
        int ans = s.length();

        for (int target = 1; target <= maxCnt; ++target) {
            vector<int> f(27, 0);
            f[25] = min(cnt[25], abs(cnt[25] - target));
            for (int i = 24; i >= 0; --i) {
                int x = cnt[i];
                f[i] = f[i + 1] + min(x, abs(x - target));
                int y = cnt[i + 1];
                if (y < target) {
                    int cost = (x >= target) ? max(x - target, target - y) : max(x, target - y);
                    f[i] = min(f[i], f[i + 2] + cost);
                }
            }
            ans = min(ans, f[0]);
        }
        return ans;
    }
};

class Solution {
    public int makeStringGood(String s) {
        int[] cnt = new int[26];
        for (char ch : s.toCharArray()) cnt[ch - 'a']++;
        int maxCnt = 0;
        for (int c : cnt) if (c > maxCnt) maxCnt = c;
        int ans = s.length();

        for (int target = 1; target <= maxCnt; ++target) {
            int[] f = new int[27];
            f[25] = Math.min(cnt[25], Math.abs(cnt[25] - target));
            for (int i = 24; i >= 0; --i) {
                int x = cnt[i];
                f[i] = f[i + 1] + Math.min(x, Math.abs(x - target));
                int y = cnt[i + 1];
                if (y < target) {
                    int cost = (x >= target) ? Math.max(x - target, target - y) : Math.max(x, target - y);
                    f[i] = Math.min(f[i], f[i + 2] + cost);
                }
            }
            ans = Math.min(ans, f[0]);
        }
        return ans;
    }
}

var makeStringGood = function(s) {
    const cnt = new Int32Array(26);
    for (let i = 0; i < s.length; i++) cnt[s.charCodeAt(i) - 97]++;
    let maxCnt = 0;
    for (let i = 0; i < 26; i++) if (cnt[i] > maxCnt) maxCnt = cnt[i];
    let ans = s.length;

    for (let target = 1; target <= maxCnt; target++) {
        const f = new Int32Array(27);
        f[25] = Math.min(cnt[25], Math.abs(cnt[25] - target));
        for (let i = 24; i >= 0; i--) {
            const x = cnt[i];
            f[i] = f[i + 1] + Math.min(x, Math.abs(x - target));
            const y = cnt[i + 1];
            if (y < target) {
                const cost = (x >= target) ? Math.max(x - target, target - y) : Math.max(x, target - y);
                f[i] = Math.min(f[i], f[i + 2] + cost);
            }
        }
        ans = Math.min(ans, f[0]);
    }
    return ans;
};
